struct ConfigState {
    int mode;
    void run() const { /* ... logic ... */ }
};

// 1. Value Copy Initialization
ConfigState state_A = {42};
ConfigState state_B = state_A; // B is a distinct value copy

// 2. Pointer Initialization
ConfigState* p_A = &state_A;
ConfigState* p_B = &state_B;

// 3. Member Access (Pointer vs Value)
p_A->run();
state_B.run();

// 4. Modification check (demonstrates separation)
p_A->mode = 99;
// state_B.mode still 42
p_B->mode = 100;
